from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework.permissions import IsAuthenticated
from django.contrib.gis.geos import LineString
from .models import RestrictedAirspaceZone

class FlightHazardCheckView(APIView):
    permission_classes = [IsAuthenticated]

    def post(self, request):
        waypoints = request.data.get('waypoints')
        flight_line = LineString(waypoints, srid=4326)

        # Only expose public advisory zones or private zones where the user is an authorized flight partner
        intersecting_zones = RestrictedAirspaceZone.objects.filter(
            perimeter_geom__intersects=flight_line
        ).filter(
            is_public_advisory=True
        ) | RestrictedAirspaceZone.objects.filter(
            perimeter_geom__intersects=flight_line,
            authorized_operators=request.user.operator_organization
        )

        results = [
            {
                'zone_id': z.id,
                'facility_name': z.facility_name,
                'security_level': z.security_level,
                'coordinates': z.perimeter_geom.geojson
            }
            for z in intersecting_zones
        ]
        return Response({'hazards': results})
